            aliStarted.complete();
          }
          await releaseAli.future;
          return _UserListResponse(items: [_supplierUser('ALI', 'Ali')]);
        }
        if (query == 'vali') {
          return _UserListResponse(items: [_supplierUser('VALI', 'Vali')]);
