      await tester.enterText(search, 'vali');
      await tester.pump(const Duration(milliseconds: 221));
      for (var i = 0; i < 20 && find.text('Vali').evaluate().isEmpty; i++) {
        await tester.pump(const Duration(milliseconds: 10));
