      expect(find.text('Vali'), findsOneWidget);
      expect(find.text('Ali'), findsNothing);

      releaseAli.complete();
      await tester.pumpAndSettle();
      expect(find.text('Vali'), findsOneWidget);
      expect(find.text('Ali'), findsNothing);

      await tester.pumpWidget(const SizedBox.shrink());
    }, createHttpClient: (_) => client);
  });

